style.css:
@-moz-document domain("google.com"), regexp("https?://(www\.)?google\.[a-z]+/.*") {
:root{
    --bg: #0b0d10;                  /* fons principal */
    --panel: rgba(255,255,255,0.03);/* targetes/resultats */
    --muted: #9aa0a6;               /* text secundari */
    --accent1: 120, 70, 255;        /* accent RGB (H intesità) - usa "R,G,B" */
    --accent2: 0, 200, 255;         /* accent secundari */
    --glass: rgba(255,255,255,0.02);
    --radius: 12px;
    --shadow: 0 6px 20px rgba(0,0,0,0.6);
    --accent-glow: 0 6px 30px rgba(var(--accent1),0.16);
  }

  /* Reset bàsic i fons */
  html, body, #main, #search, #hplogo {
    background: linear-gradient(180deg, var(--bg) 0%, #060708 100%) !important;
    color: #e8eef6 !important;
    font-family: "Inter", "Segoe UI", Roboto, Arial, sans-serif !important;
  }

  /* Elimina doodles massius i decoracions que embruten */
  #lga, .logo, .logo img, .lnXdpd, .RNNXgb { /* logo i header */
    filter: drop-shadow(var(--accent-glow)) !important;
  }

  /* Caixa de cerca */
  .SDkEP, .RNNXgb, .gLFyf {
    background: linear-gradient(135deg, rgba(var(--accent1),0.04), rgba(var(--accent2),0.02)) !important;
    border: 1px solid rgba(255,255,255,0.04) !important;
    box-shadow: var(--shadow) !important;
    border-radius: 999px !important;
  }

  .gLFyf {
    color: #e8eef6 !important;
  }

  /* Botons (Search / I'm Feeling) */
  .FPdoLc .gNO89b, .FPdoLc .gNO89b:visited, .Tg7LZd {
    background: linear-gradient(90deg, rgba(var(--accent1),0.12), rgba(var(--accent2),0.12)) !important;
    border: 1px solid rgba(var(--accent1),0.2) !important;
    color: #fff !important;
    box-shadow: 0 6px 20px rgba(var(--accent1),0.08), 0 1px 0 rgba(255,255,255,0.02) inset !important;
    border-radius: 10px !important;
  }

  /* Resultats */
  .g, .rc, .MjjYud {
    background: var(--panel) !important;
    border-radius: var(--radius) !important;
    padding: 14px 16px !important;
    margin: 10px 0 !important;
    transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease !important;
  }
  .g:hover, .rc:hover {
    transform: translateY(-4px) !important;
    box-shadow: 0 14px 40px rgba(0,0,0,0.6), 0 0 40px rgba(var(--accent2),0.06) !important;
    border: 1px solid rgba(var(--accent2),0.12) !important;
  }

  /* Enllaços i títols */
  .rc .yuRUbf a h3, .rc .r a h3, .yuRUbf > a {
    color: #fff !important;
    text-shadow: 0 1px 0 rgba(0,0,0,0.6) !important;
    font-weight: 600 !important;
  }
  .rc .TbwUpd, .TbwUpd a {
    color: var(--muted) !important;
  }

  /* Metadades */
  .IsZvec, .VwiC3b {
    color: #c8d0db !important;
    opacity: 0.95 !important;
  }

  /* Lateral / cards */
  .LGOjhe, .kp-blk, .xpdclose .xpdopen, .knowledge-panel {
    background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01)) !important;
    border-radius: 14px !important;
    border: 1px solid rgba(255,255,255,0.03) !important;
    box-shadow: 0 20px 50px rgba(0,0,0,0.65) !important;
  }

  /* Footer i bottom bar */
  #fbar, .QqG1Sd {
    background: transparent !important;
    color: var(--muted) !important;
    border-top: 1px solid rgba(255,255,255,0.02) !important;
  }

  /* Subtle RGB animated accent line under search */
  .RNNXgb:after {
    content: "";
    display: block;
    height: 3px;
    width: 100%;
    margin-top: 8px;
    border-radius: 99px;
    background: linear-gradient(90deg,
      rgba(var(--accent1),0.9) 0%,
      rgba(var(--accent2),0.9) 50%,
      rgba(255,120,100,0.9) 100%);
    animation: rgbShift 6s linear infinite;
    opacity: 0.9;
  }

  @keyframes rgbShift {
    0%   { background-position: 0% 50%; }
    50%  { background-position: 100% 50%; }
    100% { background-position: 0% 50%; }
  }

  /* Minimal; elimina elements sobrants que fan soroll (personalitzable) */
  .kp-wholepage, .eiUfe, .uBOhsb, .related-question-pair .y1KX7b {
    opacity: 0.98;
  }

  /* Concordança visual per a mòbils */
  @media (max-width: 720px) {
    .g, .rc { padding: 12px !important; margin: 8px 0 !important; }
    .RNNXgb:after { height: 2px; }
  }

  /* Accessibility / focus */
  :focus { outline: 2px dashed rgba(var(--accent1),0.22) !important; outline-offset: 3px !important; }

  /* Small tweaks perquè no falli la usabilitat */
  .sociable, .gbh, .gb_Va { filter: none !important; }
}
